en;border-radius:12px;border:2px solid #b89454;background:#f9ecd9;color:#4a1020;touch-action:pan-y}.dates{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:.4rem}.dates b{font-size:.67rem;letter-spacing:.19em}.dates strong{font:600 1.6rem 'Cormorant Garamond',serif}.dates hr{width:55%;border:0;border-top:1px solid #c69c50;margin:.35rem}canvas{position:absolute;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.scratch.done canvas{opacity:0;pointer-events:none;transition:opacity .9s}.scratch-controls{display:flex;justify-content:center;margin-top:1rem}.overlay{position:fixed;inset:0;z-index:30;display:flex;pointer-events:auto}.panel{position:absolute;top:0;bottom:0;width:50%;background-image:url('data:image/webp;base64,');background-size:200% 100%;background-repeat:no-repeat;transition:transform 2.2s cubic-bezier(.76,0,.15,1);will-change:transform}.panel.left{left:0;background-position:left center}.panel.right{right:0;background-position:right center}.overlay.open .left{transform:translateX(-103%)}.overlay.open .right{transform:translateX(103%)}.curtain-knot{position:absolute;top:52%;left:50%;transform:translate(-50%,-50%);z-index:3;display:grid;place-items:center;gap:6px;touch-action:none;cursor:grab;color:#fff6db;text-shadow:0 2px 5px #4c2400}.knot-disc{width:94px;height:94px;border-radius:50%;border:5px double #ffdb8c;background:radial-gradient(circle at 35% 30%,#ffebad,#9b651e 72%);box-shadow:0 5px 25px #3012009c;display:grid;place-items:center;font:700 1.6rem 'Cormorant Garamond',serif;color:#64350d}.rope{width:9px;height:110px;background:repeating-linear-gradient(145deg,#d9a747 0 5px,#fff0ad 5px 9px,#b47b25 9px 13px);border-radius:8px;box-shadow:2px 2px 5px #3b1b00}.rope:after{content:'';display:block;position:relative;top:104px;left:-10px;width:29px;height:34px;border-radius:4px 4px 13px 13px;background:linear-gradient(90deg,#ad741d,#ffe39a,#a66c14)}.pull-label{font-size:.65rem;letter-spacing:.16em;text-transform:uppercase;background:#3b0a13c9;padding:.5rem .7rem;border-radius:30px;white-space:nowrap}.overlay.open .curtain-knot{opacity:0;transition:opacity .4s}.skip{position:absolute;right:14px;bottom:calc(16px + env(safe-area-inset-bottom));z-index:4;background:#3a0b18b8;color:#fff;border:1px solid #e6c47b;border-radius:24px;padding:.5rem 1rem}.intro-title{position:absolute;top:8%;width:100%;text-align:center;z-index:2;font:600 1.4rem 'Cormorant Garamond',serif;letter-spacing:.12em;color:#f3d6a5}.opening{overflow:hidden}.opening .hero-content{opacity:0;transform:translateY(22px);transition:opacity 1.3s 1.3s,transform 1.3s 1.3s}.opening.ready .hero-content{opacity:1;transform:none}@media(min-width:800px){.couple{width:300px}.hero-content{padding-top:4rem}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}

