/* Royal wax-sealed invitation opening */
.wax-overlay{position:fixed;inset:0;z-index:9999;overflow:hidden;background:#173b35;isolation:isolate;display:block}
.wax-underlay{position:absolute;inset:0;background:radial-gradient(circle at 50% 45%,#f9e8c8 0%,#651629 75%,#350c1c);transform:scale(1.06);transition:transform 2.3s cubic-bezier(.2,.7,.2,1)}
.wax-leaf{position:absolute;top:0;bottom:0;width:50.15%;background-image:url(data:image/webp;base64,);background-repeat:no-repeat;background-size:200% 100%;filter:drop-shadow(0 0 12px #160a0a66);will-change:transform;transition:transform 2.15s cubic-bezier(.64,.05,.17,1);backface-visibility:hidden}
.wax-left{left:0;background-position:left center;transform-origin:left center}
.wax-right{right:0;background-position:right center;transform-origin:right center}
.wax-ribbon{position:absolute;top:46%;height:4.3%;width:50%;background:linear-gradient(180deg,#a8753c,#fff2d2 28%,#f5e1b6 57%,#a77a40);box-shadow:0 2px 9px #321a164d;transition:transform 1.3s ease,opacity .8s;pointer-events:none}
.wax-ribbon-left{left:0}.wax-ribbon-right{right:0}
.wax-seal{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);width:clamp(76px,18vw,116px);height:clamp(76px,18vw,116px);border-radius:50%;border:5px double #f7db91;background:radial-gradient(circle at 34% 27%,#ffecad,#bc7b24 54%,#7d4716);color:#fce7a5;box-shadow:0 0 0 4px #a46d24,0 10px 22px #220c1270,inset 0 0 0 5px #8f591e;display:grid;place-items:center;cursor:pointer;z-index:3;transition:transform .45s,opacity .45s,box-shadow .3s;touch-action:manipulation}
.wax-seal:hover,.wax-seal:focus-visible{box-shadow:0 0 0 4px #a46d24,0 0 0 10px #f3d68b55,0 10px 22px #220c1270;outline:2px solid #fff1c6;outline-offset:8px}
.seal-icon{font-size:clamp(38px,10vw,65px);line-height:1;text-shadow:0 2px 2px #6d3a16}
.wax-instruction{position:absolute;bottom:max(5%,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);z-index:4;display:flex;align-items:center;flex-direction:column;gap:12px;width:min(94%,420px);text-align:center;color:#fff4dc;font:700 clamp(13px,3.5vw,17px) Montserrat,sans-serif;letter-spacing:.08em;text-shadow:0 2px 8px #14080d,0 0 10px #14080d;background:#430e23d9;border:1px solid #ddbc78;padding:14px 12px;border-radius:14px}
.wax-fallback{border:1px solid #f6e4bd;border-radius:100px;padding:12px 24px;background:#e7c78b;color:#4a1423;font:700 14px Montserrat,sans-serif;cursor:pointer;min-height:44px}
.wax-overlay.open .wax-leaf.wax-left{transform:translateX(-105%) rotateY(-9deg)}
.wax-overlay.open .wax-leaf.wax-right{transform:translateX(105%) rotateY(9deg)}
.wax-overlay.open .wax-ribbon-left{transform:translateX(-110%);opacity:0}
.wax-overlay.open .wax-ribbon-right{transform:translateX(110%);opacity:0}
.wax-overlay.open .wax-seal{transform:translate(-50%,-50%) scale(.55) rotate(20deg);opacity:0;pointer-events:none}
.wax-overlay.open .wax-instruction{opacity:0;pointer-events:none;transition:opacity .3s}
.wax-overlay.open .wax-underlay{transform:scale(1)}
@media(min-width:700px){.wax-overlay{max-width:none}.wax-leaf{background-size:200% 100%}}
@media(prefers-reduced-motion:reduce){.wax-leaf,.wax-seal,.wax-ribbon,.wax-underlay{transition-duration:.01ms!important}}

/* Scene 3 — family blessings */
.family-scene{position:relative;min-height:100svh;padding:90px 18px 75px;background:radial-gradient(ellipse at 50% 15%,#7b293b 0%,#510b18 48%,#2c0711 100%);display:flex;align-items:center;justify-content:center;overflow:hidden}
