.family-inner{position:relative;z-index:1;width:min(100%,950px);text-align:center}
.family-kicker{font:600 12px Montserrat,sans-serif;letter-spacing:.24em;color:#e8d3a5;text-transform:uppercase}
.family-title{font:500 clamp(36px,7vw,70px)/1.08 'Cormorant Garamond',serif;color:#fff3df;margin:12px auto 16px;max-width:780px}
