.family-card h3{font:600 clamp(26px,4vw,40px)/1.1 'Cormorant Garamond',serif;margin:13px 0 8px;overflow-wrap:anywhere}
.family-card p{font:500 14px Montserrat,sans-serif;margin:0;color:#79533d}
.family-figures{height:190px;display:flex;align-items:flex-end;justify-content:center;gap:7px;margin:12px auto 10px}
.family-person{position:relative;width:75px;height:170px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end}
.family-head{width:40px;height:48px;border-radius:46% 46% 48% 48%;background:#c78e6a;position:absolute;top:8px;z-index:2;box-shadow:0 -9px 0 -3px #30221e}
.family-body{height:112px;width:67px;border-radius:25px 25px 6px 6px;background:linear-gradient(90deg,#f6ebd3,#c8a56b,#fff1d8);border:2px solid #b99352}
.family-person.mother .family-head{box-shadow:0 -10px 0 -3px #30221e, -13px 12px 0 -9px #30221e}
.family-person.mother .family-body{width:73px;background:linear-gradient(110deg,#285d4b 0 38%,#d8b873 39% 45%,#40745e 46% 100%);border-color:#c5a358;border-radius:20px 20px 5px 5px}
.family-card:nth-child(2) .family-person.mother .family-body{background:linear-gradient(110deg,#8a3445 0 38%,#d8b873 39% 45%,#a04b5a 46% 100%)}
