.family-reveal{opacity:0;transform:translateY(28px);transition:opacity .85s ease,transform .85s ease}.family-reveal.visible{opacity:1;transform:translateY(0)}
.family-nav{margin-top:18px;min-height:46px}
@media(max-width:620px){.family-scene{padding:75px 20px 60px}.family-grid{grid-template-columns:1fr;max-width:410px;margin:auto;gap:20px}.family-figures{height:155px}.family-person{transform:scale(.83);transform-origin:bottom center}.family-card{padding:22px 12px 24px}.family-scene:before{inset:10px;border-radius:100px 100px 16px 16px}}
@media(prefers-reduced-motion:reduce){.family-reveal{opacity:1;transform:none;transition:none}}
.family-figures{height:clamp(220px,27vw,330px);margin:15px auto 18px;display:flex;align-items:flex-end;justify-content:center;overflow:visible}.parents-art{height:100%;width:100%;object-fit:contain;object-position:center bottom;filter:drop-shadow(0 8px 12px rgba(64,25,22,.14))}@media(max-width:620px){.family-figures{height:240px}}

/* Master refinements: one continuous invitation canvas */
html{background:#510b18}
body{background:#510b18;min-height:100vh}
body::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(ellipse at 50% 35%,#743046 0%,#510b18 58%,#2c0711 100%)}
.scene,.family-scene{background:transparent!important;isolation:auto}
.scene>.painting{display:none!important}
.family-scene:before{border-color:#d7b36c55}
.family-card{background:linear-gradient(160deg,#f9efdb,#ead8b6)}
.wax-overlay{background:#510b18!important;opacity:1!important;visibility:visible!important}
.wax-underlay{background:radial-gradient(ellipse at center,#793448,#510b18 75%,#2c0711)!important}
.wax-leaf{height:100dvh!important;min-height:100vh!important;top:0!important;bottom:0!important;background-size:200% 100%!important;background-repeat:no-repeat!important}
.wax-left{left:0!important;background-position:left center!important}
.wax-right{right:0!important;background-position:right center!important}
.opening .hero-content{transition-delay:.25s!important}
.opening.ready .hero-content{opacity:1;transform:none}
@media(max-width:620px){.wax-overlay{width:100vw!important;max-width:none!important}.wax-leaf{width:50.2vw!important}.family-scene{padding-top:75px}}

/* Royal floral curtain entrance — continuous original invitation remains underneath */
.wax-overlay{background:#3f0b1c!important}
.wax-underlay{background:radial-gradient(ellipse at 50% 40%,#8a3547,#4a1023 70%,#270814)!important}
.royal-curtain{position:absolute;top:0;height:100%;width:50.5%;z-index:2;pointer-events:none;background-repeat:no-repeat;background-size:100% 100%;filter:sepia(.16) saturate(1.22) hue-rotate(-9deg) drop-shadow(0 0 18px rgba(18,0,8,.48));transition:transform 1.75s cubic-bezier(.22,.7,.15,1),opacity 1.45s ease;will-change:transform}
.royal-curtain.left{left:0;background-image:url(data:image/webp;base64,);background-position:left center}
.royal-curtain.right{right:0;background-image:url(data:image/webp;base64,);background-position:right center}
.wax-overlay.open .royal-curtain.left{transform:translateX(-110%);opacity:.85}
.wax-overlay.open .royal-curtain.right{transform:translateX(110%);opacity:.85}
.wax-seal{z-index:5!important}
.wax-instruction{z-index:5!important}
.wax-ribbon{z-index:3!important}
