@media(prefers-reduced-motion:reduce){.royal-curtain{transition-duration:.01ms!important}}

/* Continuous wedding events scene: uses the same global painted background */
.events-scene{position:relative;min-height:100svh;display:flex;align-items:center;justify-content:center;padding:90px 20px 100px;background:transparent!important;color:#f7e8c9;text-align:center}
.events-inner{width:min(100%,820px);margin:auto}
.events-kicker{font:600 11px Montserrat,sans-serif;letter-spacing:.26em;text-transform:uppercase;color:#e5c17a}
.events-title{font:500 clamp(38px,7vw,74px) 'Cormorant Garamond',Georgia,serif;color:#fff1d6;line-height:1.04;margin:14px 0 12px}
.events-intro{font:400 15px/1.8 Montserrat,sans-serif;color:#f1e0cc;margin:0 auto 28px;max-width:580px}
.events-ornament{color:#e4b965;letter-spacing:.5em;font-size:22px;margin:16px 0 26px}
