.event-card{border:1px solid rgba(236,197,126,.58);background:rgba(39,12,22,.46);box-shadow:inset 0 0 0 5px rgba(231,193,125,.045),0 12px 35px rgba(15,0,7,.12);padding:27px 14px 25px;border-radius:9px;backdrop-filter:blur(3px)}
.event-card h3{font:500 clamp(28px,4vw,38px) 'Cormorant Garamond',Georgia,serif;color:#f6d89c;margin:0 0 13px}
.event-date{font:600 19px Montserrat,sans-serif;color:#fff7e8;margin:0 0 10px}
.event-time{font:500 14px Montserrat,sans-serif;color:#f2d7a8;margin:0}
.venue-box{border-top:1px solid rgba(235,194,121,.4);padding-top:29px}
.venue-heading{font:500 38px 'Cormorant Garamond',Georgia,serif;color:#f6d89c;margin:4px 0 12px}
.venue-address{font:400 14px/1.8 Montserrat,sans-serif;color:#f6e9d8;max-width:600px;margin:0 auto 22px}
.venue-map{width:100%;height:clamp(260px,43vw,390px);border:2px solid rgba(236,197,126,.65);border-radius:10px;overflow:hidden;background:#eee5d9}
.venue-map iframe{width:100%;height:100%;border:0;display:block}
.venue-directions{display:inline-block;margin-top:23px;padding:14px 25px;border:1px solid #e7bf78;border-radius:100px;background:linear-gradient(135deg,#e4bc75,#b98538);color:#32101c!important;text-decoration:none;font:700 12px Montserrat,sans-serif;letter-spacing:.08em;text-transform:uppercase}
.venue-map-note{font:400 11px/1.5 Montserrat,sans-serif;color:#dbc8b6;margin-top:12px}
