/* Scene between family introduction and wedding events */
.kolam-scene{position:relative;min-height:100svh;display:flex;align-items:center;justify-content:center;overflow:hidden;isolation:isolate;background:#421a23;color:#fff5e3;text-align:center;padding:60px 18px}
.kolam-scene:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,#421a23 0%,transparent 17%,transparent 78%,#421a23 100%),linear-gradient(90deg,rgba(54,15,23,.24),transparent 22%,transparent 78%,rgba(54,15,23,.24)),var(--kolam-photo) center 50%/cover no-repeat;z-index:-2}
.kolam-scene:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(35,9,16,.6),transparent 22%,transparent 65%,rgba(35,9,16,.6));z-index:-1;pointer-events:none}
.kolam-scene .kolam-rotate{position:absolute;top:38%;left:50%;width:clamp(165px,42vw,310px);aspect-ratio:1;object-fit:contain;transform:translate(-50%,-50%);animation:kolam-turn 42s linear infinite;filter:drop-shadow(0 0 9px rgba(255,232,170,.65));opacity:.85}
@keyframes kolam-turn{from{transform:translate(-50%,-50%) rotate(0deg)}to{transform:translate(-50%,-50%) rotate(360deg)}}
.kolam-copy{position:absolute;top:8%;left:0;right:0;padding:0 18px;text-shadow:0 2px 18px #36131a}
.kolam-copy .kolam-kicker{font-size:12px;letter-spacing:.28em;text-transform:uppercase;color:#f2d8aa}
.kolam-copy h2{font-family:Georgia,serif;font-size:clamp(28px,5vw,48px);font-weight:400;margin:10px 0}
.kolam-next{position:absolute;bottom:7%;left:50%;transform:translateX(-50%);display:inline-block;white-space:nowrap;border:1px solid #d5af75;background:rgba(62,20,30,.75);padding:13px 22px;border-radius:40px;color:#ffe8b7;text-decoration:none;font-size:13px;letter-spacing:.08em;backdrop-filter:blur(5px)}
@media(max-width:600px){.kolam-scene{min-height:100svh}.kolam-scene:before{background-position:center,center,center 50%}.kolam-scene .kolam-rotate{top:39%;width:47vw}.kolam-copy{top:11%}}
@media(prefers-reduced-motion:reduce){.kolam-scene .kolam-rotate{animation:none}}

/* Scene 4 – separate, independently rotating kolam and stationary feet */
.kolam-scene.ceremony-v2{min-height:100svh;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px;padding:52px 15px 30px;background:linear-gradient(180deg,#421a23 0%,#a06b57 12%,#e7c9a8 27%,#efd9ba 75%,#f7e9d4 100%);color:#652633;overflow:hidden;isolation:isolate}
.kolam-scene.ceremony-v2:before,.kolam-scene.ceremony-v2:after{display:none}
.ceremony-heading{position:relative;z-index:3;text-align:center}.ceremony-heading p{font-size:11px;letter-spacing:.25em;text-transform:uppercase;color:#7e4439}.ceremony-heading h2{font-family:Georgia,serif;font-size:clamp(30px,5vw,55px);font-weight:400;margin:10px 0}.ceremony-heading span{color:#ad8447;font-style:italic}
.ceremony-stage{position:relative;isolation:isolate;width:min(100%,560px);aspect-ratio:1/1.11;flex:none}
.ceremony-kolam{position:absolute;left:50%;top:69%;width:69%;height:auto;z-index:1;pointer-events:none;transform-origin:center center;animation:ceremony-kolam-spin 42s linear infinite;filter:drop-shadow(0 1px 2px rgba(78,46,32,.25))}
.ceremony-feet{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;z-index:2;pointer-events:none}
