/* ===== CALENDAR BUTTON & MENU ===== */
.btn-calendar {
  background: linear-gradient(135deg, #fcedcd 0%, #e8ca8f 50%, #c4994d 100%) !important;
  color: #4a1020 !important;
  border: 1px solid #d2ad6a !important;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.6) !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  cursor: pointer !important;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.3s ease !important;
}
.btn-calendar:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45), 0 0 12px rgba(232, 202, 143, 0.5) !important;
  background: linear-gradient(135deg, #fff3dc 0%, #edd39c 50%, #cca053 100%) !important;
}
.calendar-menu {
  display: flex;
  gap: 10px;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 12px;
  padding: 8px 14px;
  background: rgba(35, 9, 16, 0.82);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(198, 164, 106, 0.5);
